installer-gui-script.script:
// Beat Key must not be running while it is replaced. Installer JS:
//   system.applications.fromIdentifier(bundleID) -> array of the RUNNING apps with that bundle id
//   system.applications.all()                    -> array of all running apps (ProcessInformation: BundlePath, pid)
//   my.result.title / .message / .type ('Fatal' = cannot continue: an open Beat Key is never replaced underneath itself)
// Returning false after setting my.result shows the message before the installer starts.
function beatKeyClosedCheck() {
  var running = [];
  try {
    var byId = system.applications.fromIdentifier('com.jshriver.orion');
    for (var i = 0; byId && i < byId.length; i++) { running.push(byId[i]); }
  } catch (e) { system.log('Beat Key check: fromIdentifier failed: ' + e); }
  if (running.length == 0) {
    // an old copy that fromIdentifier does not report: look at every running app's bundle path
    try {
      var all = system.applications.all();
      for (var j = 0; all && j < all.length; j++) {
        var p = String(all[j]['BundlePath'] || '');
        if (/\/(Beat Key|Orion)\.app\/?$/.test(p)) { running.push(all[j]); }
      }
    } catch (e2) { system.log('Beat Key check: all() failed: ' + e2); }
  }
  system.log('Beat Key check: ' + running.length + ' running copy(ies) of Beat Key');
  if (running.length == 0) { return true; }
  my.result.title = 'Beat Key is open';
  my.result.message = 'Quit Beat Key (Beat Key menu > Quit), then open this installer again.';
  my.result.type = 'Fatal';
  return false;
}
